'use strict';

// MODULES //

var groupMatchesByInputType = require( './group_matches_by_input_type.js' );


// MAIN //

/**
* Formats dtype enum pairs for the JavaScript dispatch types array.
*
* @private
* @param {Array} matches - array of match entries
* @returns {string} dtype enum pairs
*
* @example
* var matches = [
*     [ 'float32', 'float64', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_f_d_as_d_d' ],
*     [ 'float32', 'float32', '@stdlib/math/base/special/acosdf', false, null, null, 'stdlib_base_acosdf', 'stdlib_ndarray_f_f' ],
*     [ 'float64', 'float64', '@stdlib/math/base/special/acosd', false, null, null, 'stdlib_base_acosd', 'stdlib_ndarray_d_d' ],
*     [ 'float64', 'float32', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_d_f_as_d_d' ],
*     [ 'int32', 'float64', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_i_d_as_d_d' ]
* ];
* var result = formatTypesArray( matches );
* // returns <string>
*
* // In the template file, this renders as:
* //     // float32 (2)
* //     dtypes.float32.enum, dtypes.float64.enum,
* //     dtypes.float32.enum, dtypes.float32.enum,
* //
* //     // float64 (2)
* //     dtypes.float64.enum, dtypes.float64.enum,
* //     dtypes.float64.enum, dtypes.float32.enum,
* //
* //     // int32 (1)
* //     dtypes.int32.enum, dtypes.float64.enum
*/
function formatTypesArray( matches ) {
	var typeMatches;
	var inputType;
	var jsOut;
	var data;
	var idx;
	var i;
	var j;

	data = groupMatchesByInputType( matches );
	jsOut = '';
	idx = 0;
	for ( i = 0; i < data.inputTypes.length; i++ ) {
		inputType = data.inputTypes[ i ];
		typeMatches = data.grouped[ inputType ];
		jsOut += '\t// ' + inputType + ' (' + typeMatches.length + ')\n';
		for ( j = 0; j < typeMatches.length; j++ ) {
			jsOut += '\tdtypes.' + inputType + '.enum, dtypes.' + typeMatches[ j ][ 1 ] + '.enum';
			idx += 1;
			if ( idx < data.totalCount ) {
				jsOut += ',\n';
			} else {
				jsOut += '\n';
			}
		}
		if ( i < data.inputTypes.length - 1 ) {
			jsOut += '\n';
		}
	}
	return jsOut;
}


// EXPORTS //

module.exports = formatTypesArray;
